const brl=value=>value.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const hidden=new Set();let expanded=false;
const assets=[
 {id:'tbrl',symbol:'tBRL',network:'Moonbeam',amount:0,fiat:0,decimals:2,mark:'T$',tone:'cyan'},
 {id:'btc',symbol:'BTC',network:'Bitcoin',amount:0,fiat:0,decimals:8,mark:'₿',tone:'gold'},
 {id:'bscusdt',symbol:'BSCUSDT',network:'BNB Smart Chain',amount:0,fiat:0,decimals:2,mark:'T',tone:'green'},
 {id:'brl',symbol:'BRL',network:'Saldo interno',amount:1125,fiat:1125,decimals:2,mark:'R$',tone:'navy'},
 {id:'usdt',symbol:'USDT',network:'Ethereum',amount:200,fiat:1000,decimals:2,mark:'T',tone:'green'},
 {id:'eth',symbol:'ETH',network:'Ethereum',amount:0,fiat:0,decimals:8,mark:'Ξ',tone:'silver'},
 {id:'usdc',symbol:'USDC',network:'Polygon',amount:0,fiat:0,decimals:2,mark:'$',tone:'cyan'},
 {id:'tusd',symbol:'tUSD',network:'Moonbeam',amount:0,fiat:0,decimals:2,mark:'T$',tone:'navy'}
];
export function balanceCard({id,label,value,foot,dark=false},icon){const concealed=hidden.has(id);return `<div class="stat wallet-stat ${dark?'dark':''}" data-balance-card="${id}"><span class="stat-label">${label}</span><div class="balance-amount-line"><strong class="stat-value num" data-balance-value>${concealed?'••••••':brl(value)}</strong><button class="balance-eye" data-balance-toggle="${id}" aria-label="${concealed?'Mostrar':'Ocultar'} ${label.toLowerCase()}" aria-pressed="${concealed}" title="${concealed?'Mostrar':'Ocultar'} valor">${icon('eye')}</button></div><span class="stat-foot">${foot}</span></div>`;}
export function balanceDetails(icon){return `<section class="balance-details" aria-labelledby="balance-detail-title"><div class="app-section-title"><div><h2 id="balance-detail-title">Detalhamento do saldo</h2><p class="small mt8">Ativos e redes separados. Equivalências ilustrativas em reais.</p></div><span class="badge badge-blue">Dados fictícios</span></div><div class="asset-balances">${assets.slice(0,expanded?assets.length:4).map(asset=>{const concealed=hidden.has('asset-'+asset.id);return `<article class="asset-balance-card" data-asset-balance="${asset.id}"><div class="asset-identity"><span class="currency-mark ${asset.tone}" aria-hidden="true">${asset.mark}</span><div><h3>${asset.symbol}</h3><span>${asset.network}</span></div></div><div class="asset-quantity num" data-unit-amount>${concealed?'••••••':asset.amount.toLocaleString('pt-BR',{minimumFractionDigits:asset.decimals,maximumFractionDigits:asset.decimals})+' '+asset.symbol}</div><strong class="asset-fiat num" data-fiat-amount>${concealed?'••••••':brl(asset.fiat)}</strong><div class="asset-actions"><button class="balance-eye" data-asset-toggle="${asset.id}" aria-label="${concealed?'Mostrar':'Ocultar'} saldo de ${asset.symbol}" aria-pressed="${concealed}">${icon('eye')}</button><button class="balance-eye" data-asset-copy="${asset.id}" aria-label="Copiar identificador demonstrativo de ${asset.symbol}">${icon('copy')}</button><button class="balance-eye" data-wallet-action="${asset.id==='brl'?'Sacar':'Transferir'}" aria-label="${asset.id==='brl'?'Saque':'Transferência'} demonstrativo de ${asset.symbol}">${icon('up')}</button></div></article>`;}).join('')}</div><button class="more-assets" data-action="more-assets" aria-expanded="${expanded}">${expanded?'Mostrar menos ativos':'Outros ativos ('+(assets.length-4)+')'} <span aria-hidden="true">${expanded?'−':'+'}</span></button><p class="footnote">Os valores são fictícios. O saldo disponível de R$ 2.125,00 soma R$ 1.125,00 em BRL e o equivalente ilustrativo de R$ 1.000,00 em USDT. Nenhum endereço de depósito real é fornecido.</p></section>`;}
export function toggleBalance(id,value,label,button){hidden.has(id)?hidden.delete(id):hidden.add(id);const concealed=hidden.has(id),card=button.closest('[data-balance-card]');card.querySelector('[data-balance-value]').textContent=concealed?'••••••':brl(value);button.setAttribute('aria-pressed',String(concealed));button.setAttribute('aria-label',(concealed?'Mostrar ':'Ocultar ')+label.toLowerCase());button.title=concealed?'Mostrar valor':'Ocultar valor';}
export function toggleAsset(id,button){const asset=assets.find(a=>a.id===id);if(!asset)return;const key='asset-'+id;hidden.has(key)?hidden.delete(key):hidden.add(key);const concealed=hidden.has(key),card=button.closest('[data-asset-balance]');card.querySelector('[data-unit-amount]').textContent=concealed?'••••••':asset.amount.toLocaleString('pt-BR',{minimumFractionDigits:asset.decimals,maximumFractionDigits:asset.decimals})+' '+asset.symbol;card.querySelector('[data-fiat-amount]').textContent=concealed?'••••••':brl(asset.fiat);button.setAttribute('aria-pressed',String(concealed));button.setAttribute('aria-label',(concealed?'Mostrar':'Ocultar')+' saldo de '+asset.symbol);}
export function toggleOtherAssets(){expanded=!expanded;}
export async function copyAssetIdentifier(id){const asset=assets.find(a=>a.id===id);if(!asset)return false;try{await navigator.clipboard.writeText('DEMONSTRACAO-SEM-ENDERECO-'+asset.symbol);return true;}catch{return false;}}
